await page.goto('/login');
await expect(page.getByRole('main')).toBeVisible();

// Find the backdrop and landing bar by class/test id and read their stacking.
const info = await page.evaluate(() => {
  const all = Array.from(document.querySelectorAll('body *'));
  const pick = (re) => all.find((el) => re.test((el.className && el.className.toString()) + ' ' + (el.getAttribute('data-testid') || '')));
  const out = {};
  for (const [k, re] of [['backdrop', /backdrop/i], ['bar', /landing.*bar|bar.*landing|landing/i]]) {
    const el = pick(re);
    if (!el) { out[k] = null; continue; }
    const cs = getComputedStyle(el);
    const r = el.getBoundingClientRect();
    const top = document.elementFromPoint(r.left + r.width / 2, r.top + Math.min(r.height / 2, 20));
    out[k] = { z: cs.zIndex, pos: cs.position, onTop: !!top && (top === el || el.contains(top) || top.contains(el)) };
  }
  return out;
});

expect(info.backdrop).not.toBeNull();
expect(info.bar).not.toBeNull();
// Neither may be buried: both must be positioned with a positive z-index and reachable on top.
expect(info.backdrop.pos).not.toBe('static');
expect(Number(info.backdrop.z)).toBeGreaterThan(0);
expect(Number(info.bar.z)).toBeGreaterThan(0);
expect(info.bar.onTop).toBe(true);
